const DEFAULT_EXCLUSION_PATTERNS = [
  '**/node_modules/**',
  '**/.git/**',
  '**/dist/**',
  '**/build/**',
  '**/out/**',
  '**/.vite/**',
  '**/.turbo/**',
  '**/coverage/**',
  '**/.nyc_output/**',
  '**/.cache/**',
  '**/.tmp/**',
  '**/.octopus-storage/**',
  // Framework, language and tool caches that are regenerated by builds/installs.
  '**/.next/**',
  '**/.nuxt/**',
  '**/.svelte-kit/**',
  '**/.angular/**',
  '**/.parcel-cache/**',
  '**/.expo/**',
  '**/.docusaurus/**',
  '**/.vercel/**',
  '**/.netlify/**',
  '**/.serverless/**',
  '**/.terraform/**',
  '**/.gradle/**',
  '**/.pnpm-store/**',
  '**/.yarn/cache/**',
  '**/bower_components/**',
  '**/__pycache__/**',
  '**/.pytest_cache/**',
  '**/.mypy_cache/**',
  '**/.ruff_cache/**',
  '**/.tox/**',
  '**/.venv/**',
  '**/venv/**',
  '**/.DS_Store',
  '**/Thumbs.db',
  '**/*.log',
  '**/*.tmp',
  '**/*.swp',
  '**/*.swo',
  '**/*.vsix',
  '**/*.zip',
  '**/*.tar',
  '**/*.gz',
  '**/*.pdf',
];

const SENSITIVE_PATTERNS = [
  '**/*.pem',
  '**/*.key',
  '**/*.p12',
  '**/*.pfx',
  '**/id_rsa',
  '**/id_ed25519',
  '**/.npmrc',
];

function escapeRegex(value: string) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function globToRegex(pattern: string) {
  const normalized = pattern.replace(/\\/g, '/').replace(/^\.\//, '');
  let regex = '^';

  for (let index = 0; index < normalized.length; index += 1) {
    const current = normalized[index];
    const next = normalized[index + 1];

    if (current === '*' && next === '*') {
      regex += '.*';
      index += 1;
      continue;
    }

    if (current === '*') {
      regex += '[^/]*';
      continue;
    }

    if (current === '?') {
      regex += '.';
      continue;
    }

    regex += escapeRegex(current ?? '');
  }

  regex += '$';
  return new RegExp(regex, 'i');
}

export type ExclusionMatcher = {
  shouldExcludePath: (relativePath: string) => boolean;
  /**
   * True when the directory and everything beneath it is excluded, so traversal can skip it
   * entirely instead of reading (potentially huge) folders such as node_modules.
   */
  shouldExcludeDirectory?: (relativePath: string) => boolean;
  activePatterns: string[];
};

export function createExclusionMatcher(options: {
  customPatterns?: string[];
  excludeSensitiveFiles?: boolean;
}): ExclusionMatcher {
  const customPatterns = (options.customPatterns ?? []).map((item) => item.trim()).filter(Boolean);

  const activePatterns = [
    ...DEFAULT_EXCLUSION_PATTERNS,
    ...customPatterns,
    ...(options.excludeSensitiveFiles ?? false ? SENSITIVE_PATTERNS : []),
  ];

  const matchers = activePatterns.map(globToRegex);
  // A regex ending in `.*$` still matches after any suffix is appended, so if `dir/` matches,
  // every descendant path matches too. Only these patterns are safe for subtree pruning.
  const subtreeMatchers = activePatterns
    .filter((pattern) => pattern.replace(/\\/g, '/').endsWith('**'))
    .map(globToRegex);

  const normalize = (relativePath: string) => relativePath.replace(/\\/g, '/').replace(/^\.\//, '');

  return {
    shouldExcludePath(relativePath: string) {
      const normalized = normalize(relativePath);
      return matchers.some((matcher) => matcher.test(normalized));
    },
    shouldExcludeDirectory(relativePath: string) {
      const normalized = normalize(relativePath).replace(/\/+$/u, '');
      if (matchers.some((matcher) => matcher.test(normalized))) {
        return true;
      }

      const withSlash = `${normalized}/`;
      return subtreeMatchers.some((matcher) => matcher.test(withSlash));
    },
    activePatterns,
  };
}

export function getDefaultExclusionPatterns() {
  return [...DEFAULT_EXCLUSION_PATTERNS];
}
